'use strict';
const $=id=>document.getElementById(id);
const WEB=document.documentElement.dataset.web==='1';let PREVIEW=false;let base='';
let token='',bots=[],projects=[],jobs=[],activeBot='my-ai',selectedTask=null,conversation=null,editingBot=null,uploadedIcon=null,center=null,pollTimer=null,installPrompt=null,currentPage='dashboard',chatNew=false;
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function notice(text,error=false){const m=$('connectMsg');if(m){m.textContent=text;m.className='connect-msg'+(error?' error':'');m.hidden=!$('pairDialog').open;}$('notice').textContent=text;$('notice').className=error?'error':'';$('notice').hidden=false;}
function bind(id,fn){$(id).onclick=async()=>{try{await fn();}catch(e){notice(e.message,true);}};}
function controllerAddress(raw){const value=(raw||'').trim().replace(/\/+$/,'');let u;try{u=new URL(value);}catch(e){throw Error('Enter your controller address, e.g. https://my-pc.tailnet-name.ts.net');}if(u.pathname!=='/'||u.search||u.hash||u.username)throw Error('Use only the address, like https://my-pc.tailnet-name.ts.net (no path).');const local=['127.0.0.1','localhost'].includes(u.hostname);if(u.protocol!=='https:'&&!(local&&location.protocol==='http:'))throw Error(location.protocol==='https:'?'This website is HTTPS, so browsers block plain http:// controllers (mixed content). Run Enable-Remote.cmd so Tailscale gives your PC an https://….ts.net address.':'The controller address must start with https://.');return u.origin;}
async function rawFetch(path,options){options=options||{};options.headers={...(options.headers||{}),'X-Bacon-Device':deviceId()};if(PREVIEW){if(!window.BaconPreview)throw Error('Preview is unavailable.');return window.BaconPreview.request(path,options);}try{return await fetch(base+'/api/'+path,options);}catch(e){throw Error(WEB?'Can’t reach your controller at '+(base||'(no address)')+'. Check the PC is on, Start.cmd is running, Tailscale is connected on this device, and this website is in allowed_origins.':'Can’t reach the Bacon AI controller.');}}
async function api(path,body){const r=await rawFetch(path,{method:body===undefined?'GET':'POST',headers:{Authorization:'Bearer '+token,...(body===undefined?{}:{'Content-Type':'application/json'})},...(body===undefined?{}:{body:JSON.stringify(body)})});const value=await r.json();if(r.status===403&&value.blocked)showBlocked();if(!r.ok){const e=Error(value.error||'Request failed');e.status=r.status;throw e;}return value;}
async function download(path,name){const r=await rawFetch(path,{headers:{Authorization:'Bearer '+token}});if(!r.ok)throw Error('Download failed');saveBlob(await r.blob(),name);}
function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function page(name){currentPage=name;document.querySelectorAll('.page').forEach(p=>p.hidden=p.id!=='page-'+name);document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('selected',b.dataset.page===name));$('pageTitle').textContent={dashboard:'Dashboard',develop:'Develop',chat:'Chat',bots:'My bots',files:'Project files',monitor:'Control center',remote:'Remote access',help:'Help & setup'}[name];if($('mobileNav'))$('mobileNav').value=name;if(name==='files')loadFiles().catch(e=>notice(e.message,true));if(name==='monitor'){loadIntegrations();if(me?.role==='admin')loadAccounts().catch(e=>notice(e.message,true));loadModels().catch(e=>notice(e.message,true));}window.scrollTo(0,0);}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>page(b.dataset.page));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>page(b.dataset.go));document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
bind('pairButton',()=>openConnect());
