function fillSelect(node,items,value,text){const old=value??node.value;node.replaceChildren(...items.map(i=>{const o=el('option',text(i));o.value=i.id;return o;}));if(items.some(i=>i.id===old))node.value=old;}
async function connect(){await api('status');await refreshData();await refreshCenter();$('pairButton').textContent=PREVIEW?'Connect PC':'Switch';$('notice').hidden=true;await afterConnect();startPolling();}
function icon(container,bot){container.replaceChildren();if(bot.icon){const image=el('img');image.src=bot.icon;image.alt=bot.name;container.append(image);}else container.textContent=bot.emoji||'⚡';}
function updateActive(){const bot=bots.find(b=>b.id===activeBot)||bots[0];if(!bot)return;activeBot=bot.id;$('activeName').textContent=bot.name;$('activeMode').textContent=bot.mode+' agent';$('activeDescription').textContent=bot.description;icon($('activeIcon'),bot);$('instructionsState').textContent=bot.instructions?'Custom':'None';$('workload').value=bot.cloudTarget;updateBalance(bot.cloudTarget);fillSelect($('project'),projects.filter(p=>p.botId===activeBot),undefined,p=>p.name+' · '+p.kind);$('projectScope').textContent=$('project').value?'Changes are saved in this managed project with checkpoints.':'Create a project for this bot to start.';}
function updateBalance(value){$('cloudValue').replaceChildren(document.createTextNode(value),el('span','%'));$('localValue').replaceChildren(document.createTextNode(100-value),el('span','%'));}
$('workload').oninput=e=>updateBalance(Number(e.target.value));$('workload').onchange=async e=>{try{await api('settings',{botId:activeBot,cloudTarget:Number(e.target.value)});await refreshData();notice('Routing target saved for this bot. It applies to the next coding step.');}catch(e){notice(e.message,true);}};
async function refreshData(){[bots,projects,jobs]=await Promise.all([api('bots'),api('projects'),api('builds')]);for(const id of ['codingBot','chatBot','projectBot'])fillSelect($(id),bots,undefined,b=>(b.icon?'':b.emoji+' ')+b.name);if(bots.some(b=>b.id===activeBot))$('codingBot').value=activeBot;fillSelect($('fileProject'),projects,undefined,p=>p.name);updateActive();renderBots();renderTasks();renderChat();if(selectedTask){const j=jobs.find(j=>j.id===selectedTask);if(j)renderTask(j);}}
async function refreshCenter(){center=await api('control-center');renderPending(center.pendingAccounts);const host=center.host||{kind:'laptop',name:'My laptop'};$('inferenceHost').textContent='▰ Ollama · '+(host.kind==='cloud_pc'?'cloud PC':'laptop');$('hostDescription').textContent=host.kind==='cloud_pc'?host.name+' runs Bacon AI. Your laptop can stay off.':host.name+' runs Bacon AI and must stay awake.';const controls=center.controls;const state=controls.emergency?'Emergency stopped':controls.paused?'Paused':jobs.some(j=>j.state==='running')?'Working':'Ready';$('statusPill').textContent='● '+state;$('controlReason').textContent=controls.reason||'Ready for your next task';$('hardwareState').textContent=center.safety.toUpperCase();$('routingStatus').textContent=controls.reason||'Local + cloud · automatic coordination';const h=center.hardware;$('hardwareRows').replaceChildren();for(const [label,key,temp] of [['CPU','cpuPercent','cpuTempC'],['GPU','gpuPercent','gpuTempC'],['RAM','ramPercent',null]]){const row=el('div',undefined,'hardware-row'),bar=el('progress');bar.max=100;bar.value=h[key]??0;bar.setAttribute('aria-label',label+' usage');row.append(el('span',label),bar,el('span',h[key]==null?'—':Math.round(h[key])+'%'),el('span',temp&&h[temp]!=null?Math.round(h[temp])+'°C':'—','temp'));$('hardwareRows').append(row);}const q=center.allowance;$('allowanceValue').replaceChildren(document.createTextNode(q.available?Math.round(q.remainingPercent)+'% ':'— '),el('span',q.available?'remaining':'Unavailable'));$('allowanceBar').value=q.remainingPercent??0;$('allowanceDescription').textContent=q.available?`${q.source}${q.warningThreshold?' · '+q.warningThreshold+'% threshold warning':''}`:'Exact subscription usage unavailable. App request counts are not a quota estimate.';$('budget').textContent=`App call budget: ${center.requestBudget.used} / ${center.requestBudget.limit} used today · separate from ChatGPT allowance.`;$('monitorData').textContent=JSON.stringify(center,null,2);allowanceUI(center);renderBrain();countdown();}
function countdown(){const windows=center?.allowance?.windows||[];const known=windows.filter(w=>Number.isFinite(w.resetsAt)).sort((a,b)=>a.remainingPercent-b.remainingPercent);if(!known.length){$('resetTime').textContent='Reset time unavailable';return;}const seconds=Math.max(0,Math.floor(known[0].resetsAt-Date.now()/1000));$('resetTime').textContent=seconds?`Reported window resets in ${Math.floor(seconds/3600)}h ${Math.floor(seconds%3600/60)}m ${seconds%60}s`:'Reported reset time reached · refresh allowance';}
function startPolling(){clearTimeout(pollTimer);const loop=async()=>{try{await refreshData();await refreshCenter();}catch(e){$('statusPill').textContent='● Disconnected';}pollTimer=setTimeout(loop,3000);};pollTimer=setTimeout(loop,3000);}
setInterval(countdown,1000);
