bind('startTask',async()=>{if(!$('project').value)throw Error('Create or choose a project first.');const j=await api('tasks',{prompt:$('codingPrompt').value,botId:activeBot,projectId:$('project').value,mode:'coding'});selectedTask=j.id;$('codingPrompt').value='';await refreshData();notice('Task queued. Your controller will plan, code, and save checkpoints.');});
function taskButton(j){const b=el('button',undefined,'task-item'),text=el('span',j.prompt.slice(0,110));text.append(el('small',(j.bot?.name||'My AI')+' · '+new Date(j.created).toLocaleString()));b.append(text,el('em',j.state.replaceAll('_',' ')));b.onclick=()=>{selectedTask=j.id;page('develop');renderTask(j);};return b;}
function renderTasks(){const coding=jobs.filter(j=>j.mode!=='chatbot'&&j.mode!=='general');for(const [id,items] of [['recentTasks',coding.slice(0,4)],['codingTasks',coding]]){const parent=$(id);parent.replaceChildren();if(!items.length)parent.append(el('p','Your next project starts with an idea.','empty'));else items.forEach(j=>parent.append(taskButton(j)));}}
function actionButton(parent,text,fn,cls){const b=el('button',text,cls);b.onclick=async()=>{try{await fn();}catch(e){notice(e.message,true);}};parent.append(b);return b;}
function renderTask(j){const card=el('article',undefined,'card');card.append(el('h3',j.prompt.slice(0,150)),el('p',j.state.replaceAll('_',' ')+' · '+(j.verification||'Verification pending')));if(j.error)card.append(el('p',j.error,'error'));if(j.plan?.length){const list=el('ol');j.plan.forEach(s=>list.append(el('li',s)));card.append(list);}if(j.workflow==='bacon'&&j.projectId){const bar=el('div',undefined,'step-progress');bar.title='Agent steps used';const max=6;for(let i=0;i<max;i++){const s=el('span');if(i<(j.stepIndex||0)+(j.state==='ready'?1:0))s.className='done';bar.append(s);}card.append(bar);}if(j.reply)card.append(richText(j.reply));if(j.events?.length){card.append(el('h4','Progress log'),taskLog(j.events));}if(j.lastChecks){card.append(el('h4',j.lastChecks.ok?'Checks ✓':'Checks ✗ — automatic repair uses this output'),el('pre',j.lastChecks.output));}if(j.runtimeTest)card.append(el('pre','Studio smoke test: '+JSON.stringify(j.runtimeTest,null,2)));if(j.state==='awaiting_approval'){const a=el('div',undefined,'card approval');a.append(el('h3','Your approval is needed'),el('p',j.approval.message),el('pre',JSON.stringify(j.approval.paths||j.approval.tools,null,2)));actionButton(a,'Approve this action',async()=>{await api('approve',{id:j.id,approve:true});await refreshData();},'primary');actionButton(a,'Decline',async()=>{await api('approve',{id:j.id,approve:false});await refreshData();});card.append(a);}const buttons=el('div',undefined,'buttons');if(j.workflow==='bacon'&&['stopped','failed','needs_attention'].includes(j.state))actionButton(buttons,'Resume saved task',async()=>{await api('resume-task',{id:j.id});await refreshData();},'primary');if(j.package){actionButton(buttons,'Download Roblox place',()=>download('place/'+j.id,'Bacon-AI-'+j.id+'.rbxlx'),'primary');card.append(el('pre',j.package.instructions));}if(j.projectId){actionButton(buttons,'View project files',()=>{$('fileProject').value=j.projectId;page('files');});actionButton(buttons,'Continue / fix',()=>{activeBot=j.botId;updateActive();$('project').value=j.projectId;$('codingPrompt').value='';$('codingPrompt').focus();notice('Describe the next change or error. Existing project files are included automatically.');});}card.append(buttons);$('taskDetail').replaceChildren(card);}
