function miniIcon(bot){const s=el('span',undefined,'bot-icon mini');if(bot)icon(s,bot);return s;}
$('conversationSelect').onchange=()=>{conversation=$('conversationSelect').value||null;chatNew=!conversation;renderChat();};
bind('sendChat',async()=>{if(!$('chatPrompt').value.trim())throw Error('Type a message first.');const j=await api('tasks',{prompt:$('chatPrompt').value,botId:$('chatBot').value,mode:'chatbot',conversationId:conversation});conversation=j.conversationId;chatNew=false;$('chatPrompt').value='';await refreshData();});
function renderChat(){$('chatHistory').replaceChildren();const botId=$('chatBot').value;const chatBotObj=bots.find(b=>b.id===botId);icon($('chatBotIcon'),chatBotObj||{emoji:'⚡'});if(!conversation&&!chatNew){const latest=jobs.find(j=>j.botId===botId&&j.mode==='chatbot');if(latest)conversation=latest.conversationId;}const threads=[...new Map(jobs.filter(j=>j.botId===botId&&j.mode==='chatbot').map(j=>[j.conversationId,{id:j.conversationId,prompt:j.prompt}])).values()];fillSelect($('conversationSelect'),[{id:'',prompt:'New conversation'},...threads],conversation||'',j=>j.prompt.slice(0,60));if(!conversation)$('chatHistory').append(el('div','I’m Bacon AI, an AI assistant created by Diab Productions!\n\nI can be whoever you choose me to be. Whether you need a coding partner, a chatbot, or a personal AI assistant, I’m here to help.\n\nI specialize in coding and software development, but I can also help you with conversations, creative projects, problem-solving, and much more.\n\nYou choose my purpose. I’ll help you bring your ideas to life.\n\nSo, what would you like to create today? 🚀','chat-message'));for(const j of [...jobs].reverse().filter(j=>j.botId===botId&&j.conversationId===conversation)){const user=el('div',undefined,'chat-message user');user.append(el('small','You'),document.createTextNode(j.prompt));const reply=el('div',undefined,'chat-message');const who=el('small');who.append(miniIcon(bots.find(b=>b.id===j.botId)||j.bot),' '+(j.bot?.name||'AI'));reply.append(who,j.reply?richText(j.reply):document.createTextNode(j.error||j.state.replaceAll('_',' ')+'…'));$('chatHistory').append(user,reply);}}
function renderBots(){$('botList').replaceChildren();for(const b of bots){const card=el('article',undefined,'card'),profile=el('div',undefined,'bot-profile'),image=el('div',undefined,'bot-icon');icon(image,b);const info=el('div');info.append(el('h4',b.name),el('p',b.mode+' · '+b.cloudTarget+'% cloud target'));profile.append(image,info);card.append(profile,el('p',b.description),el('p','Instructions: '+(b.instructions?'Custom':'None'),'micro'));const buttons=el('div',undefined,'buttons');actionButton(buttons,'Edit',()=>editBot(b));actionButton(buttons,'Export',async()=>{if(!confirm('Export this bot’s instructions, personality and icon? Review its text for private information. Conversations, project files and credentials are excluded.'))return;const value=await api('bot-export?id='+encodeURIComponent(b.id));saveBlob(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}),'bacon-bot.json');});card.append(buttons);$('botList').append(card);}}
function editBot(bot){editingBot=bot?.id||null;uploadedIcon=bot?.icon||null;$('botIconFile').value='';iconMsg('');setTimeout(showIconPreview);$('botDialogTitle').textContent=bot?'Edit '+bot.name:'Create your bot';for(const [id,key] of [['botName','name'],['botDescription','description'],['botInstructions','instructions'],['botPersonality','personality']])$(id).value=bot?.[key]||'';$('botMode').value=bot?.mode||'coding';$('botEmoji').value=bot?.emoji||'⚡';$('botTarget').value=bot?.cloudTarget??60;$('botLanguage').value=bot?.projectSettings?.preferredLanguage||'';$('botTestStyle').value=bot?.projectSettings?.testStyle||'';$('botIconFile').value='';$('botDialog').showModal();}
bind('createBot',()=>editBot(null));for(const emoji of ['⚡','🥓','🤖','🧠','🎮','🛠️','🚀','🐱','💻','🌸']){const b=el('button',emoji);b.type='button';b.onclick=()=>{$('botEmoji').value=emoji;if(!uploadedIcon)showIconPreview();else iconMsg('Emoji saved as a backup. Your photo is still used; tap “Use emoji instead” to switch.');};$('emojiPicker').append(b);}
bind('clearBotIcon',()=>{uploadedIcon=null;$('botIconFile').value='';showIconPreview();iconMsg('');});
/* Bot photo: decode any image the browser can read (iPhone HEIC included, since Safari decodes it), centre-crop to 256 px and compress to a small data URL. */
let iconWork=null;
function iconMsg(text,error){const m=$('botIconMsg');m.textContent=text||'';m.classList.toggle('error',!!error);}
function showIconPreview(){const p=$('botIconPreview');p.replaceChildren();if(uploadedIcon){const im=el('img');im.src=uploadedIcon;im.alt='Bot photo';p.append(im);}else p.textContent=$('botEmoji').value||'⚡';}
function loadImage(file){return new Promise((ok,bad)=>{const url=URL.createObjectURL(file);const im=new Image();im.onload=()=>{URL.revokeObjectURL(url);ok(im);};im.onerror=()=>{URL.revokeObjectURL(url);bad(Error('This browser can\u2019t open that photo. Try a JPEG or PNG (on iPhone: Settings → Camera → Formats → Most Compatible).'));};im.src=url;});}
async function shrinkImage(file,size=256){if(!file.type.startsWith('image/')&&!/\.(heic|heif|jpe?g|png|webp|gif)$/i.test(file.name))throw Error('Choose an image file.');if(file.size>25e6)throw Error('That photo is over 25 MB. Choose a smaller one.');
 const im=await loadImage(file);const side=Math.min(im.naturalWidth,im.naturalHeight);if(!side)throw Error('That image is empty.');const c=document.createElement('canvas');c.width=c.height=size;const g=c.getContext('2d');g.fillStyle='#ffffff';g.fillRect(0,0,size,size);g.imageSmoothingQuality='high';
 g.drawImage(im,(im.naturalWidth-side)/2,(im.naturalHeight-side)/2,side,side,0,0,size,size);let q=.85,out=c.toDataURL('image/jpeg',q);while(out.length>120000&&q>.4){q-=.15;out=c.toDataURL('image/jpeg',q);}return out;}
$('botIconFile').onchange=()=>{const file=$('botIconFile').files[0];if(!file)return;iconMsg('Preparing photo…');iconWork=shrinkImage(file).then(url=>{uploadedIcon=url;showIconPreview();iconMsg('Photo ready ('+Math.round(url.length*3/4/1024)+' KB). It replaces the emoji.');}).catch(e=>{iconMsg(e.message,true);}).finally(()=>{iconWork=null;});};
$('botForm').onsubmit=async e=>{e.preventDefault();if(iconWork){iconMsg('Finishing the photo…');await iconWork;}try{await api('bots',{id:editingBot,bot:{name:$('botName').value,description:$('botDescription').value,instructions:$('botInstructions').value,personality:$('botPersonality').value,mode:$('botMode').value,emoji:$('botEmoji').value,icon:uploadedIcon,cloudTarget:Number($('botTarget').value),projectSettings:{preferredLanguage:$('botLanguage').value,testStyle:$('botTestStyle').value}}});$('botDialog').close();await refreshData();}catch(e){notice(e.message,true);}};
bind('importBot',()=>$('botImportFile').click());$('botImportFile').onchange=async()=>{try{const file=$('botImportFile').files[0];if(!file)return;if(file.size>500000)throw Error('Bot configuration too large.');await api('bot-import',JSON.parse(await file.text()));await refreshData();notice('Bot imported. No conversations or credentials imported.');}catch(e){notice(e.message,true);}};
$('fileProject').onchange=()=>loadFiles().catch(e=>notice(e.message,true));async function loadFiles(){const id=$('fileProject').value;if(!id||!token)return;$('fileName').textContent='Select a file';$('fileContent').replaceWith(Object.assign(el('pre','Your source will appear here.'),{id:'fileContent'}));const [files,checkpoints]=await Promise.all([api('project-files?id='+id),api('checkpoints?id='+id)]);$('fileList').replaceChildren();for(const [path,content] of Object.entries(files)){const b=el('button',path,'file-button');b.onclick=()=>{$('fileName').textContent=path;$('fileContent').replaceWith(Object.assign(codeView(content),{id:'fileContent'}));};$('fileList').append(b);}if(!Object.keys(files).length)$('fileList').append(el('p','No files yet.'));$('checkpointList').replaceChildren();for(const c of checkpoints){const row=el('div',undefined,'checkpoint');row.append(el('span',new Date(c.created*1000).toLocaleString()+' · '+c.reason));actionButton(row,'View changes',async()=>renderDiff(await api('checkpoint-diff?id='+id+'&checkpoint='+c.id)));actionButton(row,'Restore',async()=>{if(!confirm('Restore this checkpoint? Current managed files will be replaced, with a checkpoint kept first.'))return;await api('restore',{projectId:id,checkpoint:c.id,confirmed:true});await loadFiles();notice('Checkpoint restored.');});$('checkpointList').append(row);}}
bind('downloadProject',()=>{const id=$('fileProject').value;if(!id)throw Error('Choose a project.');return download('project-download?id='+id,'Bacon-AI-project.zip');});
async function loadIntegrations(){if(!token)return;try{const rows=await api('integrations');$('integrations').replaceChildren();for(const r of rows){const p=el('p');p.append(el('strong',r.name+': '),document.createTextNode(r.status));$('integrations').append(p);}}catch(e){notice(e.message,true);}}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('install').hidden=false;});bind('install',async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;}});
