/* ---- Coding UX: markdown, code blocks, highlighting, diffs, task log ---- */
const KEYWORDS=new Set('and as async await break case catch class const continue def default del do elif else end except export extends false False finally for from function if import in is let local local new nil none None not null of or pass private public raise repeat return self static super switch then this throw true True try type typeof until var void while with yield'.split(' '));
function highlight(code){const frag=document.createDocumentFragment();const re=/(\/\/[^\n]*|#[^\n]*|--[^\n]*|\/\*[\s\S]*?\*\/)|("(?:\\.|[^"\\\n])*"|'(?:\\.|[^'\\\n])*'|`(?:\\.|[^`\\])*`)|(\b\d+(?:\.\d+)?\b)|([A-Za-z_]\w*)(?=\s*\()|([A-Za-z_]\w*)/g;let last=0,m;while((m=re.exec(code))){if(m.index>last)frag.append(code.slice(last,m.index));const [t]=m;let cls=m[1]?'tk-c':m[2]?'tk-s':m[3]?'tk-n':m[4]?(KEYWORDS.has(t)?'tk-k':'tk-f'):(KEYWORDS.has(t)?'tk-k':null);frag.append(cls?el('span',t,cls):t);last=re.lastIndex;}if(last<code.length)frag.append(code.slice(last));return frag;}
function copyText(text,button){const done=()=>{button.textContent='Copied ✓';setTimeout(()=>button.textContent='Copy',1500);};if(navigator.clipboard&&window.isSecureContext)navigator.clipboard.writeText(text).then(done,()=>fallbackCopy(text,done));else fallbackCopy(text,done);}
function fallbackCopy(text,done){const t=el('textarea');t.value=text;t.style.position='fixed';t.style.opacity='0';document.body.append(t);t.select();try{document.execCommand('copy');done();}catch(e){notice('Copy failed; select the code manually.',true);}t.remove();}
function codeBlock(code,lang){const box=el('div',undefined,'code-block'),head=el('div',undefined,'code-head');head.append(el('span',lang||'code'));const b=el('button','Copy');b.type='button';b.onclick=()=>copyText(code,b);head.append(b);const pre=el('pre'),c=el('code');c.append(highlight(code));pre.append(c);box.append(head,pre);return box;}
function inline(text,parent){const parts=text.split(/(`[^`\n]+`|\*\*[^*\n]+\*\*)/);for(const p of parts){if(p.length>2&&p.startsWith('`')&&p.endsWith('`'))parent.append(el('code',p.slice(1,-1)));else if(p.length>4&&p.startsWith('**')&&p.endsWith('**'))parent.append(el('strong',p.slice(2,-2)));else if(p)parent.append(p);}}
function richText(text){const root=el('div',undefined,'md');const re=/```([\w+#.-]*)[^\n]*\n([\s\S]*?)(?:```|$)/g;let last=0,m;const para=t=>{t=t.replace(/^\n+|\n+$/g,'');if(t){const p=el('p');inline(t,p);root.append(p);}};while((m=re.exec(text||''))){para(text.slice(last,m.index));root.append(codeBlock(m[2].replace(/\n$/,''),m[1]));last=re.lastIndex;}para((text||'').slice(last));return root;}
function codeView(content){const pre=el('pre',undefined,'code-view');for(const line of content.split('\n')){const s=el('span',undefined,'ln');s.append(highlight(line));s.append('\n');pre.append(s);}return pre;}
function renderDiff(result){$('diffTitle').textContent='Changes · '+result.reason;const body=$('diffBody');body.replaceChildren();if(!result.changes.length)body.append(el('p','No file changes after this checkpoint.'));for(const c of result.changes){const box=el('div',undefined,'diff-file');box.append(el('h4',c.status.toUpperCase()+' · '+c.path));const pre=el('pre');for(const line of c.diff.split('\n')){const cls=line.startsWith('+++')||line.startsWith('---')?null:line.startsWith('+')?'d-add':line.startsWith('-')?'d-del':line.startsWith('@@')?'d-hunk':null;pre.append(cls?el('span',line,cls):line+'\n');}box.append(pre);body.append(box);}$('diffDialog').showModal();}
function taskLog(events){const list=el('ol',undefined,'task-log');for(const e of events){const cls=/passed|completed|saved/i.test(e)?'ok':/fail|unavailable|exhausted|error/i.test(e)?'bad':/cloud/i.test(e)?'cloud':'';list.append(el('li',e,cls));}return list;}

/* ---- Progressive allowance warnings (official numbers only; app budget labelled separately) ---- */
const THRESHOLDS=[75,50,25,10,5,0];
function levelFor(r){return r==null?'unknown':r<=10?'red':r<=25?'orange':r<=50?'yellow':'green';}
function crossedThreshold(prev,now){if(now==null)return null;let hit=null;for(const t of THRESHOLDS)if(now<=t&&(prev==null||prev>t))hit=t;return hit;}
function toast(text,level){const t=el('div',text,'toast');t.dataset.level=level;$('toasts').append(t);setTimeout(()=>t.remove(),9000);}
function setMeter(id,fill,percent,level){$(id).dataset.level=level;$(fill).style.width=(percent??0)+'%';}
let limitPrompted=false;
function allowanceUI(c){const q=c.allowance||{},r=q.available?q.remainingPercent:null,level=levelFor(r);setMeter('allowanceMeter','allowanceFill',r,level);setMeter('chatMeter','chatFill',r,level);$('chatAllowanceText').textContent=r==null?'Unavailable (no '+SRC()+')':Math.round(r)+'% left · '+SRC()+'';
const b=c.requestBudget||{},br=b.remainingPercent;setMeter('budgetMeter','budgetFill',br,levelFor(br));
const store=JSON.parse(localStorage.getItem(warnKey())||'{}');
if(r!=null){const hit=crossedThreshold(store.allowance,r);if(hit!=null)toast(hit===0?'ChatGPT allowance exhausted ('+SRC()+').':`ChatGPT allowance: ${Math.round(r)}% left (crossed ${hit}%, ${SRC()}).`,level);if(r>(store.allowance??-1)+20)limitPrompted=false;store.allowance=r;}
if(br!=null){const hit=crossedThreshold(store.budget,br);if(hit!=null)toast(hit===0?`App daily cloud budget used (${b.used}/${b.limit} calls, counted by Bacon AI — not your ChatGPT quota).`:`App daily cloud budget: ${b.used}/${b.limit} calls used (counted by Bacon AI — not your ChatGPT quota).`,levelFor(br));store.budget=br;}
const mode=c.cloudMode||{localOnly:false};if(store.localOnly!==undefined&&store.localOnly!==mode.localOnly)toast(mode.localOnly?'Switched to local only: '+mode.reason+'.':'Cloud is available again. Hybrid routing resumed.',mode.localOnly?'orange':'green');store.localOnly=mode.localOnly;localStorage.setItem(warnKey(),JSON.stringify(store));
$('localBadge').hidden=$('chatLocalBadge').hidden=!mode.localOnly;$('localBadge').title=mode.reason||'';
const banner=$('allowanceBanner');let msg=null;if(q.available&&r!=null&&r<=25)msg=r<=0?'ChatGPT allowance exhausted. New work runs locally until it resets.':`ChatGPT allowance low: ${Math.round(r)}% left (${SRC()}).`;else if(b.exhausted)msg='App daily cloud call budget used. Continuing locally (this is Bacon AI\u2019s own counter, not your ChatGPT quota).';
if(msg&&banner.dataset.dismissed!==msg){banner.hidden=false;banner.dataset.level=r!=null&&r<=25?level:'orange';$('allowanceBannerText').textContent=msg;}else if(!msg)banner.hidden=true;
if(((q.available&&q.exhausted)||mode.cloudBlocked)&&!mode.chosen&&!limitPrompted&&!$('limitDialog').open){limitPrompted=true;const reset=(q.windows||[]).map(w=>w.resetsAt).filter(Number.isFinite).sort()[0];$('limitReset').textContent=reset?'Reported reset: '+new Date(reset*1000).toLocaleString():'Reset time not reported.';$('limitDialog').showModal();}}
bind('dismissBanner',()=>{$('allowanceBanner').dataset.dismissed=$('allowanceBannerText').textContent;$('allowanceBanner').hidden=true;});
bind('limitLocal',async()=>{await api('cloud-mode',{mode:'local'});$('limitDialog').close();notice('Local only. Total performance may be lower until cloud is re-enabled.');await refreshCenter();});
bind('limitPause',async()=>{await api('cloud-mode',{mode:'pause'});$('limitDialog').close();notice('Paused until the limit resets. Press Resume in Control center when it does.');await refreshCenter();});
bind('localBadge',async()=>{if(!confirm('Allow cloud (ChatGPT/Codex) again for new steps?'))return;await api('cloud-mode',{mode:'auto'});await refreshCenter();});
