(()=>{const ios=/iphone|ipad|ipod/i.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);const standalone=navigator.standalone||matchMedia('(display-mode: standalone)').matches;if(ios&&!standalone&&!localStorage.getItem('bacon-ios-hint'))$('iosInstall').hidden=false;})();
