/* ---- Preview mode: in-browser mock API, never contacts a controller ---- */
function SRC(){return PREVIEW?'sample data, preview':'official Codex report';}
function warnKey(){return PREVIEW?'bacon-warn-preview':'bacon-warn';}
async function startPreview(){if(!window.BaconPreview)throw Error('Preview is unavailable.');clearTimeout(pollTimer);PREVIEW=true;token='preview';base='';window.BaconPreview.reset();localStorage.removeItem('bacon-warn-preview');document.body.classList.add('preview');$('previewBar').hidden=false;$('pairDialog').close();await connect();notice('Preview mode: sample data, not real AI. Nothing leaves this browser.');}
