document.querySelectorAll('[data-sim]').forEach(b=>b.onclick=async()=>{try{if(!PREVIEW)return;const v=b.dataset.sim;if(v==='budget')window.BaconPreview.setBudgetUsed(12);else window.BaconPreview.setRemaining(Number(v));await refreshCenter();}catch(e){notice(e.message,true);}});
