let models=null;
const MODE_HELP={hybrid:'Uses both Ollama on your PC and ChatGPT (Codex), routed by the split below.',cloud:'ChatGPT only: never uses Ollama. Still needs a controller (laptop or cloud PC) running Bacon AI. When the limit is hit you choose: switch to local or pause.',local:'PC only: never uses ChatGPT. Uses only your Ollama model.'};
function renderBrain(){const b=center?.brain;if(!b)return;const g=b.global,eff=b.bots?.[activeBot]||{mode:g.brainMode,power:g.power};
 document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('selected',x.dataset.mode===g.brainMode));
 document.querySelectorAll('[data-power]').forEach(x=>x.classList.toggle('selected',x.dataset.power===g.power));
 $('brainModeHelp').textContent=MODE_HELP[g.brainMode];const p=b.power[g.power];$('brainPowerHelp').textContent=`${p.label}: up to ${Math.round(p.budgetFactor*100)}% of the app's daily cloud call budget · Codex reasoning effort ${p.reasoningEffort} · ${p.parallel?'local and cloud in parallel':'one model at a time (lighter on the GPU)'}.`;
 const bot=bots.find(x=>x.id===activeBot);const target=bot?.cloudTarget??60;$('brainSplitValue').textContent=target+'%';document.querySelectorAll('[data-preset]').forEach(x=>x.classList.toggle('selected',Number(x.dataset.preset)===target));$('brainSplit').hidden=eff.mode!=='hybrid';$('splitPresets').hidden=eff.mode!=='hybrid';
 $('botBrainOverride').value=bot?.brain?.brainMode||'';
 const label={hybrid:'Hybrid',cloud:'ChatGPT only',local:'PC only'}[eff.mode];$('brainChip').textContent=`🧠 ${label} · ${b.power[eff.power].label}`+(eff.mode!=='cloud'?' · '+(eff.localModel||''):'')+(eff.mode==='hybrid'?` · ${target}% cloud`:'');
 if(document.activeElement!==$('cloudModel'))$('cloudModel').value=g.cloudModel||'';}
async function setBrain(settings,scope='global'){await api('brain',{scope,botId:activeBot,settings});await refreshData();await refreshCenter();}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=async()=>{try{await setBrain({brainMode:b.dataset.mode});notice('Brain Mode: '+b.textContent+'.');}catch(e){notice(e.message,true);}});
document.querySelectorAll('[data-power]').forEach(b=>b.onclick=async()=>{try{await setBrain({power:b.dataset.power});notice('Brain power: '+b.textContent+'.');}catch(e){notice(e.message,true);}});
document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=async()=>{try{await api('settings',{botId:activeBot,cloudTarget:Number(b.dataset.preset)});await refreshData();await refreshCenter();notice('Cloud split target '+b.dataset.preset+'% (routing target, not a guaranteed split).');}catch(e){notice(e.message,true);}});
$('botBrainOverride').onchange=async()=>{try{const v=$('botBrainOverride').value;await setBrain(v?{brainMode:v}:{clear:true},'bot');}catch(e){notice(e.message,true);}};
bind('brainChip',()=>page('monitor'));
bind('saveCloudModel',async()=>{await setBrain({cloudModel:$('cloudModel').value.trim()});notice('Cloud model saved.');});
async function loadModels(){if(!token)return;models=await api('models');$('modelInfo').textContent=models.ollamaError||`GPU memory assumed: ${models.vramGB} GB. VRAM figures are estimates.`;$('cloudModelNote').textContent=models.cloudModels.note;
 const rows=$('modelList');rows.replaceChildren();const names=new Set(models.catalog.map(c=>c.name));
 const all=[...models.catalog,...models.installed.filter(m=>!names.has(m.name)).map(m=>({name:m.name,installed:true,note:'Installed',sizeGB:m.sizeGB}))];
 for(const m of all){const row=el('div',undefined,'model-row'+(m.name===models.active?' active':''));const info=el('div');const title=el('strong',m.name);info.append(title);
  if(m.recommended)title.append(el('span','Recommended','tag ok'));if(m.vramGB!=null)title.append(el('span',m.fits?'Fits ~'+m.vramGB+' GB':'Needs ~'+m.vramGB+' GB',m.fits?'tag ok':'tag warn'));if(m.installed)title.append(el('span','Installed','tag'));
  info.append(el('small',(m.note||'')+(m.sizeGB?` · ${m.sizeGB} GB download`:'')));row.append(info);
  const pull=models.pulls?.[m.name];
  if(m.name===models.active)row.append(el('span','Active','tag ok'));
  else if(m.installed)actionButton(row,'Use',async()=>{await setBrain({localModel:m.name});await loadModels();notice('Local model: '+m.name);},'primary');
  else actionButton(row,pull?.state==='pulling'?'Downloading…':'Pull',async()=>{if(!confirm(`Download ${m.name} with Ollama${m.sizeGB?' (~'+m.sizeGB+' GB)':''}? It uses disk space and bandwidth.`))return;await api('model-pull',{name:m.name,confirmed:true});await loadModels();});
  if(pull){const bar=el('progress');bar.max=100;if(pull.percent!=null)bar.value=pull.percent;row.append(bar,el('small',pull.state+' · '+(pull.status||'')+(pull.percent!=null?' '+pull.percent+'%':'')));}
  rows.append(row);}
 if(models.pulls&&Object.values(models.pulls).some(p=>p.state==='pulling'))setTimeout(()=>loadModels().catch(()=>{}),2000);}
/* ---- Saved connections, family accounts, device ID, blocked screen, approval links ---- */
const PROFILE_KEY='bacon-profiles',LAST_KEY='bacon-last';let authMethod='token',editingProfile=null,pendingApproval=null,me=null;
function deviceId(){let d=localStorage.getItem('bacon-device');if(!d||!/^[A-Za-z0-9_-]{16,64}$/.test(d)){const b=crypto.getRandomValues(new Uint8Array(18));d=btoa(String.fromCharCode(...b)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');localStorage.setItem('bacon-device',d);}return d;}
function profiles(){try{const v=JSON.parse(localStorage.getItem(PROFILE_KEY)||'[]');return Array.isArray(v)?v:[];}catch(e){return [];}}
function saveProfiles(list){localStorage.setItem(PROFILE_KEY,JSON.stringify(list));}
function migrateLegacy(){const oldBase=localStorage.getItem('bacon-base'),oldToken=localStorage.getItem('bacon-token')||sessionStorage.getItem('bacon-token');if(oldToken&&!profiles().length){saveProfiles([{id:crypto.randomUUID(),name:'My PC',kind:'pc',address:WEB?(oldBase||''):'',auth:'token',secret:oldToken}]);}localStorage.removeItem('bacon-base');localStorage.removeItem('bacon-token');sessionStorage.removeItem('bacon-token');}
function showBlocked(){document.querySelectorAll('dialog[open]').forEach(d=>d.close());$('blockedScreen').hidden=false;clearTimeout(pollTimer);}
const AUTH_SCREENS={token:['🔑 Owner sign-in','Only for the owner. Enter your owner key.','Sign in as owner'],account:['👤 Sign in','Sign in with the account the owner approved.','Sign in'],signup:['✨ Create account','Create a regular account. We email you a code, then the owner approves you.','Create account']};
function setAuthMethod(m){authMethod=m;if($('verifyFields'))hideVerify();$('authChooser').hidden=!!m;$('authScreen').hidden=!m;$('pairSubmit').hidden=!m;
 $('tokenFields').hidden=m!=='token';$('accountFields').hidden=m!=='account';$('signupFields').hidden=m!=='signup';if(m){const [t,hint,btn]=AUTH_SCREENS[m];$('authTitle').textContent=t;$('authHint').textContent=hint;$('pairSubmit').textContent=btn;}}
document.querySelectorAll('[data-auth]').forEach(b=>b.onclick=()=>setAuthMethod(b.dataset.auth));
function renderProfiles(){const box=$('profileButtons');box.replaceChildren();const last=localStorage.getItem(LAST_KEY);
 for(const p of profiles()){const row=el('div',undefined,'profile-row');const b=el('button',undefined,'big-option'+(p.id===last?' primary':''));b.type='button';b.append((p.kind==='cloud'?'☁️ ':'💻 ')+p.name,el('small',(p.kind==='cloud'?'ChatGPT only':'My PC')+' · '+(p.auth==='account'?p.email:'owner')+(p.id===last?' · last used':'')));b.onclick=()=>connectProfile(p).catch(e=>notice(e.message,true));
  const edit=el('button','✎','icon-button');edit.type='button';edit.title='Edit';edit.onclick=()=>showForm(p.kind,p);
  const forget=el('button','✕','icon-button');forget.type='button';forget.title='Forget';forget.onclick=()=>{if(!confirm('Forget "'+p.name+'" on this device? (Your account and the controller are not affected.)'))return;saveProfiles(profiles().filter(x=>x.id!==p.id));if(localStorage.getItem(LAST_KEY)===p.id)localStorage.removeItem(LAST_KEY);renderProfiles();};
  row.append(b,edit,forget);box.append(row);}
 const cloud=profiles().find(p=>p.kind==='cloud');$('chatgptOnly').querySelector('small').textContent=cloud?'Uses "'+cloud.name+'" and switches Brain Mode to ChatGPT only.':'Needs a small always-on server (one-time setup).';
 $('connectPc').querySelector('small').textContent=profiles().some(p=>p.kind==='pc')?'Add another PC or account':'Your laptop: Hybrid, ChatGPT only or PC only';}
function openConnect(message){if(!$('blockedScreen').hidden)return;$('connectMsg').hidden=true;$('connectHome').hidden=false;$('pairForm').hidden=true;renderProfiles();if(!$('pairDialog').open)$('pairDialog').showModal();if(message)notice(message,true);}
function showForm(kind,profile){editingProfile=profile||null;$('connectHome').hidden=true;$('pairForm').hidden=false;$('profileKind').value=profile?.kind||kind;$('profileName').value=profile?.name||(kind==='cloud'?'Oracle cloud':'My PC');$('pairAddress').value=profile?.address||'';$('addressLabel').hidden=!WEB;$('pairToken').value='';$('accEmail').value=profile?.email||'';$('accPassword').value='';setAuthMethod(profile?profile.auth:null);$('cloudExplainer').hidden=kind!=='cloud';$('pairIntro').textContent=kind==='cloud'?'Enter your cloud server once. Next time it\u2019s one tap.':'Enter your PC\u2019s address, then choose how you sign in.';}
bind('connectPc',()=>showForm('pc'));bind('pairBack',()=>{if(authMethod&&!editingProfile){setAuthMethod(null);return;}openConnect();});
bind('chatgptOnly',async()=>{if(PREVIEW){await api('brain',{scope:'global',settings:{brainMode:'cloud'}});$('pairDialog').close();await refreshCenter();notice('Preview: Brain Mode set to ChatGPT only (sample).');return;}const cloud=profiles().find(p=>p.kind==='cloud');if(!cloud){showForm('cloud');return;}await connectProfile(cloud,{chatgptOnly:true});});
function leavePreview(){if(!PREVIEW)return;clearTimeout(pollTimer);PREVIEW=false;$('previewBar').hidden=true;document.body.classList.remove('preview');}
async function connectProfile(p,opts={}){leavePreview();base=WEB?controllerAddress(p.address):'';token=p.secret;try{await connect();}catch(e){if(e.status===401&&p.auth==='account'){showForm(p.kind,p);setAuthMethod('account');throw Error('Your sign-in expired. Enter your password again.');}throw e;}
 localStorage.setItem(LAST_KEY,p.id);if($('pairDialog').open)$('pairDialog').close();
 if(opts.chatgptOnly||p.kind==='cloud'){if(me?.role==='admin'){await api('brain',{scope:'global',settings:{brainMode:'cloud'}});await refreshCenter();notice('Connected to '+p.name+' · Brain Mode: ChatGPT only.');}else notice('Connected to '+p.name+'. (The owner controls the Brain Mode.)');}else notice('Connected to '+p.name+'.');}
async function loginAccount(address,email,password){const r=await fetch((WEB?address:'')+'/api/login',{method:'POST',headers:{'Content-Type':'application/json','X-Bacon-Device':deviceId()},body:JSON.stringify({email,password})}).catch(()=>{throw Error('Can\u2019t reach that controller. Check the address and Tailscale.');});const v=await r.json();if(r.status===403&&v.blocked)showBlocked();if(!r.ok)throw Error(v.error||'Sign-in failed');return v;}
$('pairForm').onsubmit=async e=>{e.preventDefault();if(authMethod==='signup'){try{await startSignup();}catch(err){notice(err.message,true);}return;}try{const kind=$('profileKind').value,address=WEB?controllerAddress($('pairAddress').value):'';const name=$('profileName').value.trim()||(kind==='cloud'?'Oracle cloud':'My PC');let profile={id:editingProfile?.id||crypto.randomUUID(),name,kind,address,auth:authMethod};
 if(authMethod==='token'){const t=$('pairToken').value.trim()||(editingProfile?.auth==='token'?editingProfile.secret:'');if(!t)throw Error('Enter your owner key.');profile.secret=t;}
 else{const email=$('accEmail').value.trim(),pw=$('accPassword').value;if(!email||!pw)throw Error('Enter your email and password.');const v=await loginAccount(address,email,pw);profile.secret=v.session;profile.email=v.user.email;$('accPassword').value='';}
 await connectProfile(profile,{chatgptOnly:kind==='cloud'});saveProfiles([...profiles().filter(x=>x.id!==profile.id),profile]);localStorage.setItem(LAST_KEY,profile.id);}catch(err){notice(err.message,true);}};
async function publicPost(path,body){const address=WEB?controllerAddress($('pairAddress').value):'';const r=await fetch(address+'/api/'+path,{method:'POST',headers:{'Content-Type':'application/json','X-Bacon-Device':deviceId()},body:JSON.stringify(body)}).catch(()=>{throw Error('Can\u2019t reach that controller.');});const v=await r.json();if(r.status===403&&v.blocked)showBlocked();if(!r.ok)throw Error(v.error||'Request failed');return v;}
async function signupPost(path,body){return PREVIEW?api(path,body):publicPost(path,body);}
let verifyEmail='',resendTimer=null;
function showVerify(email,message){verifyEmail=email;$('signupFields').hidden=true;$('accountFields').hidden=true;$('tokenFields').hidden=true;$('verifyFields').hidden=false;$('pairSubmit').hidden=true;$('verifyText').textContent=message;$('verifyCode').value='';$('verifyCode').focus();cooldown(60);}
function hideVerify(){$('verifyFields').hidden=true;$('pairSubmit').hidden=!authMethod;clearInterval(resendTimer);}
function cooldown(sec){clearInterval(resendTimer);const b=$('verifyResend');let left=sec;const tick=()=>{b.disabled=left>0;b.textContent=left>0?`Resend code (${left}s)`:'Resend code';left--;if(left<-1)clearInterval(resendTimer);};tick();resendTimer=setInterval(tick,1000);}
async function startSignup(){const email=$('suEmail').value.trim(),pw=$('suPassword').value,name=$('accName').value.trim();if(!email)throw Error('Enter your email.');if(pw.length<10)throw Error('Use a password of at least 10 characters.');
 const v=await signupPost('signup',{email,password:pw,name});$('suPassword').value='';showVerify(v.email,v.message);notice(v.message);}
bind('verifyResend',async()=>{const v=await signupPost('signup-resend',{email:verifyEmail});notice(v.message);cooldown(60);});
bind('verifySubmit',async()=>{const code=$('verifyCode').value.trim();if(!/^\d{6}$/.test(code))throw Error('Enter the 6-digit code from the email.');const v=await signupPost('signup-verify',{email:verifyEmail,code});hideVerify();setAuthMethod('account');$('accEmail').value=verifyEmail;notice(v.message+' Sign in here once you’re approved.');});
$('verifyCode').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('verifySubmit').click();}});
async function afterConnect(){if(PREVIEW){me={id:'owner',role:'admin',owner:true};}else{try{me=await api('me');}catch(e){me=null;}}$('accountsCard').hidden=me?.role!=='admin';renderMyAccount();renderPending(center?.pendingAccounts);if(me?.role==='admin')loadAccounts().catch(()=>{});
 if(pendingApproval&&me?.role==='admin'){const code=pendingApproval;pendingApproval=null;const info=await api('approval-link?t='+encodeURIComponent(code)).catch(e=>{notice(e.message,true);return null;});if(info){$('approvalText').textContent=(info.action==='approve'?'Approve':'Decline')+' the account '+info.email+' (currently '+info.status+')?';$('approvalAgeLabel').hidden=info.action!=='approve';$('approvalAge').value='';$('approvalConfirm').onclick=async()=>{try{const age=info.action==='approve'?Number($('approvalAge').value):undefined;if(info.action==='approve'&&!(Number.isInteger(age)&&age>=3&&age<=120))throw Error('Enter their age (3–120).');await api('approval-link',{t:code,confirm:true,age});$('approvalDialog').close();notice('Done: '+info.email+' '+(info.action==='approve'?'approved':'declined')+'.');loadAccounts();}catch(e){notice(e.message,true);}};$('approvalDialog').showModal();}}
 else if(pendingApproval)notice('Use Owner sign-in (owner key) to confirm that account decision.',true);}
async function loadAccounts(){const data=await api('accounts');$('accountsInfo').textContent=(data.emailConfigured?'Sign-up emails go to the owner address.':'Sign-up emails are off (run scripts/setup_email.py to turn them on).')+(data.emailError?' Last email error: '+data.emailError:'')+` Blocked: ${data.bans.devices} device IDs, ${data.bans.tailnet.length} Tailscale identities.`;
 const list=$('accountsList');list.replaceChildren();if(!data.accounts.length)list.append(el('p','No family accounts yet. Share the website link; new sign-ups appear here.','micro'));
 for(const u of data.accounts){const row=el('div',undefined,'account-row');const head=el('div');head.append(el('strong',u.name+' '),el('span',u.email+' ','micro'),el('span',u.status,'status '+u.status));row.append(head,el('span',`${u.devices} device(s)`+(u.tailnet.length?' · '+u.tailnet.join(', '):''),'micro'));
  const controls=el('div',undefined,'form-grid');const role=el('select');for(const r of ['user','admin']){const o=el('option',r);o.value=r;role.append(o);}role.value=u.role;role.disabled=!me?.owner;role.title=me?.owner?'':'Only the owner can make admins';role.onchange=()=>act('update',u.id,{changes:{role:role.value}});
  const budget=el('input');budget.type='number';budget.min=0;budget.max=1000;budget.placeholder='No personal limit';budget.value=u.cloudBudget??'';budget.onchange=()=>act('update',u.id,{changes:{cloudBudget:budget.value===''?null:Number(budget.value)}});
  const l1=el('label','Role');l1.append(role);const l2=el('label','Cloud calls per day');l2.append(budget);controls.append(l1,l2);
  const age=el('input');age.type='number';age.min=3;age.max=120;age.placeholder='Not set (filtered)';age.value=u.age??'';age.disabled=!me?.owner;age.onchange=()=>act('update',u.id,{changes:{age:age.value===''?null:Number(age.value)}});const l3=el('label','Age'+(me?.owner?'':' (owner sets)'));l3.append(age);
  const sw=el('label',undefined,'toggle-row');const box=el('input');box.type='checkbox';box.checked=!!u.swearing;box.disabled=!u.adult;box.onchange=()=>act('update',u.id,{changes:{swearing:box.checked}});sw.append(box,u.adult?' Swearing mode (adult)':' Kid-friendly filter always on (minor or age not set)');controls.append(l3,sw);row.append(controls);
  const b=el('div',undefined,'buttons');if(u.status!=='active'&&u.status!=='banned')actionButton(b,'Approve',()=>{const n=age.value===''?null:Number(age.value);if(n===null&&me?.owner){age.focus();throw Error('Enter their age first (under 18 keeps the kid-friendly filter on).');}return act('update',u.id,{changes:{status:'active',...(me?.owner?{age:n}:{})}});},'primary');if(u.status==='active'||u.status==='pending')actionButton(b,'Deny',()=>act('update',u.id,{changes:{status:'denied'}}));
  if(u.status==='banned')actionButton(b,'Unban',()=>act('unban',u.id));else actionButton(b,'Ban',async()=>{if(confirm('Ban '+u.email+'? This blocks the account, its device IDs and its Tailscale identity.'))await act('ban',u.id);},'danger');
  actionButton(b,'Remove',async()=>{if(confirm('Remove '+u.email+'? Their sign-in stops working. (Bans stay.)'))await act('remove',u.id);});row.append(b);list.append(row);}}
function renderMyAccount(){const card=$('myAccountCard');if(!me||me.owner){card.hidden=true;return;}card.hidden=false;
 $('myAccountText').textContent=`Signed in as ${me.email}. `+(me.adult?(me.swearing?'Swearing mode is on: the word filter is off for your chats.':'Kid-friendly filter is on. As an adult you can turn on Swearing mode.'):'Kid-friendly filter is on. Only adults can change this (the owner sets ages).');
 $('swearRow').hidden=!me.adult;$('swearToggle').checked=!!me.swearing;}
$('swearToggle').onchange=async()=>{try{await api('me-settings',{swearing:$('swearToggle').checked});me=await api('me');renderMyAccount();notice(me.swearing?'Swearing mode on.':'Kid-friendly filter on.');}catch(e){notice(e.message,true);$('swearToggle').checked=!!me?.swearing;}};
function renderPending(list){const bar=$('pendingBar'),badge=$('pendingBadge');list=list||[];bar.hidden=!list.length||me?.role!=='admin';if(badge){badge.hidden=bar.hidden;badge.textContent=list.length;}if(bar.hidden)return;
 $('pendingTitle').textContent=`👪 ${list.length} new account${list.length>1?'s':''} waiting for approval`;const box=$('pendingList');box.replaceChildren();
 for(const u of list){const row=el('div',undefined,'pending-row');row.append(el('span',(u.name||'')+' · '+u.email));const age=el('input');age.type='number';age.min=3;age.max=120;age.placeholder='Age';age.inputMode='numeric';age.setAttribute('aria-label','Age of '+u.email);if(!me?.owner)age.hidden=true;
  const b=el('div',undefined,'buttons');actionButton(b,'Approve',async()=>{const n=Number(age.value);if(me?.owner&&!(Number.isInteger(n)&&n>=3&&n<=120)){age.focus();throw Error('Enter their age (3–120) to approve. Under 18 keeps the kid-friendly filter on.');}await api('accounts',{action:'update',id:u.id,changes:{status:'active',...(me?.owner?{age:n}:{})}});notice(u.email+' approved.');await refreshCenter();},'primary');
  actionButton(b,'Decline',async()=>{await api('accounts',{action:'update',id:u.id,changes:{status:'denied'}});notice(u.email+' declined.');await refreshCenter();});row.append(age,b);box.append(row);}}
bind('pendingToggle',()=>{const l=$('pendingList');l.hidden=!l.hidden;$('pendingToggle').textContent=l.hidden?'Review':'Hide';});
async function act(action,id,extra={}){await api('accounts',{action,id,...extra});await loadAccounts();}
function startup(){migrateLegacy();deviceId();const m=location.hash.match(/approval=([A-Za-z0-9_.-]{20,400})/);if(m){pendingApproval=m[1];history.replaceState(null,'',location.pathname+location.search);}
 const list=profiles(),last=list.find(p=>p.id===localStorage.getItem(LAST_KEY))||(list.length===1?list[0]:null);
 if(last)connectProfile(last).catch(e=>openConnect(e.message+' Tap a saved connection or Switch.'));else setTimeout(()=>openConnect(),300);}
startup();
